from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for character-prefix reuse in serialized rows."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional source dataframe and basic shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert a scalar to evaluator text, mapping scalar missing values to ''. """
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute LCP length with binary-searched C-level string slices."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Return exact sorted-adjacent serialized character-Trie reuse."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            cls._lcp(ordered[i - 1], ordered[i])
            for i in range(1, len(ordered))
        )

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize every row using its row-specific source-column order."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells, mode: int = 0) -> List[int]:
        """Rank columns by length-weighted repeated-value potential."""
        n, m = cells.shape
        ranked = []

        for column in range(m):
            counts = {}
            total_length = 0

            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
                total_length += len(value)

            repetition = sum(
                count * (count - 1)
                for count in counts.values()
            )
            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )

            if mode == 0:
                score = weighted
            elif mode == 1:
                score = weighted + repetition
            else:
                score = repetition * max(1, total_length // max(1, n))

            ranked.append((score, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    @staticmethod
    def _potential(codes, lengths, rows, column) -> int:
        """Compute local length-weighted repetition from factorized column codes."""
        if len(rows) < 2:
            return 0

        local_codes = codes[rows, column]
        counts = np.bincount(
            local_codes,
            minlength=len(lengths[column])
        )
        return int(np.sum(
            lengths[column] * counts * (counts - 1)
        ))

    def _conditional_orders(self, cells) -> List[List[int]]:
        """
        Build a bounded depth-three conditional prefix tree.

        Each column is factorized once. At every node, up to sixteen promising
        remaining columns are inspected, the best repeated field is emitted,
        and rows are partitioned by its integer code. Leaves receive the
        globally ranked unused suffix.
        """
        n, m = cells.shape

        if n == 0:
            return []
        if m <= 1:
            return [list(range(m)) for _ in range(n)]

        codes = np.empty((n, m), dtype=np.int32)
        lengths = []

        for column in range(m):
            mapping = {}
            column_lengths = []
            next_code = 0

            for row in range(n):
                value = cells[row, column]
                code = mapping.get(value)

                if code is None:
                    code = next_code
                    mapping[value] = code
                    column_lengths.append(len(value))
                    next_code += 1

                codes[row, column] = code

            lengths.append(np.asarray(column_lengths, dtype=np.int64))

        global_tail = self._global_order(cells, 0)
        result = [None] * n
        membership_left = 4 * n

        def finish(rows, prefix, remaining):
            """Assign the globally ranked unused suffix to every leaf row."""
            remaining_set = set(remaining)
            suffix = [
                column for column in global_tail
                if column in remaining_set
            ]
            order = prefix + suffix

            for row in rows:
                result[row] = order[:]

        def visit(rows, prefix, remaining, depth):
            """Select one repeated field, partition rows, and recurse safely."""
            nonlocal membership_left

            if (
                len(rows) < 3
                or depth >= 3
                or not remaining
                or membership_left < len(rows)
            ):
                finish(rows, prefix, remaining)
                return

            # First use cheap global potential to bound local examination.
            rough = []
            for column in remaining:
                global_counts = np.bincount(
                    codes[:, column],
                    minlength=len(lengths[column])
                )
                estimate = int(np.sum(
                    lengths[column]
                    * global_counts
                    * (global_counts - 1)
                ))
                rough.append((estimate, column))

            rough.sort(key=lambda item: (-item[0], item[1]))
            candidates = [
                column for _, column in rough[:16]
            ]

            best_column = None
            best_gain = 0

            for column in candidates:
                gain = self._potential(
                    codes, lengths, rows, column
                )
                if gain > best_gain:
                    best_gain = gain
                    best_column = column

            if best_column is None or best_gain <= 0:
                finish(rows, prefix, remaining)
                return

            groups = {}
            for row in rows:
                code = int(codes[row, best_column])
                groups.setdefault(code, []).append(row)

            # A non-partitioning field cannot improve conditional structure.
            if len(groups) <= 1:
                finish(rows, prefix, remaining)
                return

            membership_left -= len(rows)

            next_remaining = [
                column for column in remaining
                if column != best_column
            ]
            next_prefix = prefix + [best_column]

            for group_rows in groups.values():
                visit(
                    group_rows,
                    next_prefix,
                    next_remaining,
                    depth + 1
                )

        visit(list(range(n)), [], list(range(m)), 0)
        return result

    def _candidate(self, cells, orders):
        """Serialize, score exactly, and sort rows by serialized text."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row)
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate bounded global and recursive candidates and return the best."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(
                    raw[row, column]
                )

        global_a = self._global_order(cells, 0)
        global_b = self._global_order(cells, 1)
        conditional = self._conditional_orders(cells)

        candidates = [
            [global_a[:] for _ in range(n)],
            [global_b[:] for _ in range(n)],
            conditional,
        ]

        best = None

        for orders in candidates:
            score, strings, row_order = self._candidate(
                cells, orders
            )

            signature = tuple(orders[0]) if orders else ()
            tie_break = tuple(-column for column in signature)
            choice = (score, tie_break)

            if best is None or choice > best[0]:
                best = (
                    choice,
                    strings,
                    row_order,
                    orders,
                )

        _, strings, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]

            output[destination, :] = [
                raw[source, column]
                for column in source_order
            ]

            column_orders.append([
                df.columns[column]
                for column in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders


